func resolveOAuthCredentials(cmd *cobra.Command, flags *rootFlags, cfg *config.Config, clientID, clientSecret string) (string, string, error) {
	explicitClientID := clientID
	if clientID == "" && cfg != nil {
		clientID = cfg.ClientID
	}
	if clientSecret == "" && cfg != nil && (explicitClientID == "" || explicitClientID == cfg.ClientID) {
		clientSecret = cfg.ClientSecret
	}
	if clientID != "" {
		return clientID, clientSecret, nil
	}
	if flags.noInput {
		return "", "", fmt.Errorf("OAuth2 client ID is required; pass --client-id, set POSTIEE_CLIENT_ID, or run 'postiee login' without --no-input")
	}
	reader := bufio.NewReader(cmd.InOrStdin())
	printOAuthCredentialHint(cmd.ErrOrStderr())
	clientID, err := promptOAuthCredential(cmd, reader, "OAuth2 Client ID")
	if err != nil {
		return "", "", err
	}
	if clientID == "" {
		return "", "", fmt.Errorf("OAuth2 client ID is required")
	}
	if clientSecret == "" {
		clientSecret, err = promptOAuthCredential(cmd, reader, "OAuth2 Client Secret (press Enter if not required)")
		if err != nil {
			return "", "", err
		}
	}
	return clientID, clientSecret, nil
}

func printOAuthCredentialHint(w io.Writer) {
	fmt.Fprintln(w, "Create OAuth credentials at: https://www.linkedin.com/oauth/v2/authorization")
}

func promptOAuthCredential(cmd *cobra.Command, reader *bufio.Reader, label string) (string, error) {
	fmt.Fprintf(cmd.ErrOrStderr(), "%s: ", label)
	line, err := reader.ReadString('\n')
	if err != nil && err != io.EOF {
		return "", fmt.Errorf("reading %s: %w", strings.ToLower(label), err)
	}
	return strings.TrimSpace(line), nil
}

func newAuthStatusCmd(flags *rootFlags) *cobra.Command {
	return &cobra.Command{
		Use:   "status",
		Short: "Show authentication status",
		RunE: func(cmd *cobra.Command, args []string) error {
			cfg, err := config.Load(flags.configPath)
			if err != nil {
				return err
			}

			w := cmd.OutOrStdout()
			authed := cfg.AccessToken != ""
			refusals := cfg.CredentialRefusalSummaries()
			credentialRefused := len(refusals) > 0
			// JSON envelope: {authenticated, verified, source, config}.
			if flags.asJSON {
				out := map[string]any{
					"authenticated": authed,
					"verified":      false,
					"source":        cfg.AuthSource,
					"config":        cfg.Path,
				}
				if credentialRefused {
					out["credential_refused"] = true
					out["credential_refusals"] = refusals
				}
				if printErr := printJSONFiltered(w, out, flags); printErr != nil {
					return printErr
				}
				if !authed && credentialRefused {
					return authErr(cfg.CredentialRefusalError())
				}
				return nil
			}

			if !authed && credentialRefused {
				fmt.Fprintf(w, "  %s Credentials present but refused.\n", red("FAIL"))
				for _, refusal := range refusals {
					fmt.Fprintf(w, "  %s\n", refusal)
				}
				return authErr(cfg.CredentialRefusalError())
			}

			if !authed {
				fmt.Fprintf(w, "  %s Not authenticated. Run 'postiee login' to authenticate.\n", red("FAIL"))
				return nil
			}

			if cfg.TokenExpiry.IsZero() {
				fmt.Fprintf(w, "  %s Credentials present (not verified; no expiry info)\n", green("OK"))
			} else if time.Now().Before(cfg.TokenExpiry) {
				fmt.Fprintf(w, "  %s Credentials present (not verified; expires %s)\n", green("OK"), cfg.TokenExpiry.Format(time.RFC3339))
			} else {
				if cfg.RefreshToken != "" {
					fmt.Fprintf(w, "  %s Token expired (will auto-refresh on next request)\n", yellow("WARN"))
				} else {
					fmt.Fprintf(w, "  %s Token expired. Run 'postiee login' to re-authenticate.\n", red("FAIL"))
				}
			}

			if cfg.AuthSource != "" {
				fmt.Fprintf(w, "  source: %s\n", cfg.AuthSource)
			}
			return nil
		},
	}
}

func newAuthLogoutCmd(flags *rootFlags) *cobra.Command {
	return &cobra.Command{
		Use:   "logout",
		Short: "Remove stored authentication tokens",
		RunE: func(cmd *cobra.Command, args []string) error {
			cfg, err := config.Load(flags.configPath)
			if err != nil {
				return err
			}
			if err := cfg.ClearTokens(); err != nil {
				return fmt.Errorf("clearing tokens: %w", err)
			}
			// JSON envelope: {cleared: true}. The OAuth flavor does not
			// surface a "note" key because env-var creds aren't part of
			// this auth flow's contract.
			if flags.asJSON {
				return printJSONFiltered(cmd.OutOrStdout(), map[string]any{
					"cleared": true,
				}, flags)
			}
			fmt.Fprintf(os.Stderr, "Logged out. Tokens removed.\n")
			return nil
		},
	}
}

// generatePKCEVerifier returns a fresh RFC 7636 code verifier: 32 bytes of
// CSPRNG output, base64url-encoded without padding (43 chars, within the
// 43-128 range the RFC requires).
func generatePKCEVerifier() (string, error) {
	verifierBytes := make([]byte, 32)
	if _, err := rand.Read(verifierBytes); err != nil {
		return "", fmt.Errorf("generating PKCE verifier: %w", err)
	}
	return base64.RawURLEncoding.EncodeToString(verifierBytes), nil
}

// pkceCodeChallengeS256 derives the S256 code challenge for a verifier:
// base64url(SHA-256(verifier)) without padding.
func pkceCodeChallengeS256(verifier string) string {
	sum := sha256.Sum256([]byte(verifier))
	return base64.RawURLEncoding.EncodeToString(sum[:])
}

func openBrowser(url string) {
	var cmd *exec.Cmd
	switch runtime.GOOS {
	case "darwin":
		cmd = exec.Command("open", url)
	case "linux":
		cmd = exec.Command("xdg-open", url)
	case "windows":
		cmd = exec.Command("rundll32", "url.dll,FileProtocolHandler", url)
	default:
		return
	}
	cmd.Start()
}
